(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var Utils = {
    uuid: function () {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        var v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
      });
    },
    store: function (namespace, data) {
      if (arguments.length > 1) {
        return localStorage.setItem(namespace, JSON.stringify(data));
      } else {
        var store = localStorage.getItem(namespace);
        return (store && JSON.parse(store)) || [];
      }
    }
  };

  var App = {
    init: function () {
      this.todos = Utils.store(STORAGE_KEY);
      this.bindEvents();
      this.render();
    },
    bindEvents: function () {
      var todoList = document.querySelector('.todo-list');
      var newTodo = document.querySelector('.new-todo');
      var toggleAll = document.querySelector('#toggle-all');
      var clearCompleted = document.querySelector('.clear-completed');

      newTodo.addEventListener('keyup', this.create.bind(this));
      todoList.addEventListener('click', this.destroy.bind(this));
      todoList.addEventListener('click', this.toggle.bind(this));
      todoList.addEventListener('dblclick', this.edit.bind(this));
      todoList.addEventListener('keyup', this.editKeyup.bind(this));
      todoList.addEventListener('focusout', this.editBlur.bind(this));
      todoList.addEventListener('click', this.destroy.bind(this));
      toggleAll.addEventListener('change', this.toggleAll.bind(this));
      clearCompleted.addEventListener('click', this.clearCompleted.bind(this));

      window.addEventListener('hashchange', this.filter.bind(this));
    },
    render: function () {
      var todoList = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var toggleAll = document.querySelector('#toggle-all');
      var newTodo = document.querySelector('.new-todo');

      var html = '';
      var completed = 0;
      var active = 0;

      this.todos.forEach(function (todo) {
        if (todo.completed) {
          completed++;
        } else {
          active++;
        }

        var completedClass = todo.completed ? ' completed' : '';
        html += '<li data-id="' + todo.id + '" class="' + completedClass + '">' +
          '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + this.escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + this.escapeHtml(todo.title) + '">' +
          '</li>';
      }.bind(this));

      todoList.innerHTML = html;

      if (this.todos.length > 0) {
        main.style.display = '';
        footer.style.display = '';
      } else {
        main.style.display = 'none';
        footer.style.display = 'none';
      }

      toggleAll.checked = completed === this.todos.length && this.todos.length > 0;

      var count = document.querySelector('.todo-count');
      count.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

      var clearBtn = document.querySelector('.clear-completed');
      clearBtn.style.display = completed > 0 ? '' : 'none';

      this.filter();
    },
    escapeHtml: function (str) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(str));
      return div.innerHTML;
    },
    create: function (e) {
      var input = e.target;
      var val = input.value.trim();

      if (e.which !== ENTER_KEY || !val) {
        return;
      }

      this.todos.push({
        id: Utils.uuid(),
        title: val,
        completed: false
      });

      input.value = '';
      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    destroy: function (e) {
      if (e.target.className !== 'destroy') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      this.todos = this.todos.filter(function (todo) {
        return todo.id !== id;
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    toggle: function (e) {
      if (e.target.className !== 'toggle') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      this.todos.forEach(function (todo) {
        if (todo.id === id) {
          todo.completed = !todo.completed;
        }
      });

      Utils.store(STORAGE_KEY, this.todos);

      // Update the li in place to avoid detaching elements from the DOM
      var todo = this.todos.find(function (t) { return t.id === id; });
      if (todo.completed) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      e.target.checked = todo.completed;

      this._updateCounts();
      this.filter();
    },
    toggleAll: function (e) {
      var checked = e.target.checked;

      this.todos.forEach(function (todo) {
        todo.completed = checked;
      });

      Utils.store(STORAGE_KEY, this.todos);

      // Update all li elements in place to avoid detaching elements from the DOM
      var todoList = document.querySelector('.todo-list');
      var lis = todoList.querySelectorAll('li');
      lis.forEach(function (li) {
        var dataId = li.getAttribute('data-id');
        var todo = this.todos.find(function (t) { return t.id === dataId; });
        if (todo) {
          if (todo.completed) {
            li.classList.add('completed');
          } else {
            li.classList.remove('completed');
          }
          var checkbox = li.querySelector('.toggle');
          checkbox.checked = todo.completed;
        }
      }.bind(this));

      this._updateCounts();
      this.filter();
    },
    _updateCounts: function () {
      var completed = 0;
      var active = 0;

      this.todos.forEach(function (todo) {
        if (todo.completed) {
          completed++;
        } else {
          active++;
        }
      });

      var toggleAll = document.querySelector('#toggle-all');
      toggleAll.checked = completed === this.todos.length && this.todos.length > 0;

      var count = document.querySelector('.todo-count');
      count.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

      var clearBtn = document.querySelector('.clear-completed');
      clearBtn.style.display = completed > 0 ? '' : 'none';
    },
    edit: function (e) {
      if (e.target.tagName !== 'LABEL') {
        return;
      }

      var li = e.target.closest('li');
      li.classList.add('editing');

      var editInput = li.querySelector('.edit');
      editInput.focus();
    },
    editKeyup: function (e) {
      if (e.target.className !== 'edit') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      var key = e.which || e.keyCode;
      if (key === ENTER_KEY) {
        e.target.blur();
      } else if (key === ESCAPE_KEY) {
        this.cancelEdit(e.target);
      }
    },
    editBlur: function (e) {
      if (e.target.className !== 'edit') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var val = e.target.value.trim();

      if (val) {
        this.todos.forEach(function (todo) {
          if (todo.id === id) {
            todo.title = val;
          }
        });
        Utils.store(STORAGE_KEY, this.todos);
      } else {
        this.todos = this.todos.filter(function (todo) {
          return todo.id !== id;
        });
        Utils.store(STORAGE_KEY, this.todos);
      }

      li.classList.remove('editing');
      this.render();
    },
    cancelEdit: function (input) {
      var li = input.closest('li');
      var id = li.getAttribute('data-id');
      var todo = this.todos.find(function (t) {
        return t.id === id;
      });

      if (todo) {
        input.value = todo.title;
      }

      li.classList.remove('editing');
    },
    clearCompleted: function () {
      this.todos = this.todos.filter(function (todo) {
        return !todo.completed;
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    filter: function () {
      var hash = window.location.hash || '#/';
      var todoList = document.querySelector('.todo-list');
      var links = document.querySelectorAll('.filters a');

      links.forEach(function (link) {
        if (link.getAttribute('href') === hash) {
          link.classList.add('selected');
        } else {
          link.classList.remove('selected');
        }
      });

      var todos = todoList.querySelectorAll('li');
      todos.forEach(function (li) {
        var id = li.getAttribute('data-id');
        var todo = this.todos.find(function (t) {
          return t.id === id;
        });

        if (!todo) return;

        var show = true;
        if (hash === '#/active' && todo.completed) {
          show = false;
        } else if (hash === '#/completed' && !todo.completed) {
          show = false;
        }

        li.style.display = show ? '' : 'none';
      }.bind(this));
    }
  };

  App.init();
})();

